def _text_from_part(part: Any) -> str:
    if part is None:
        return ""
    if isinstance(part, str):
        return part
    if str(_field(part, "type") or "").strip().lower() in _NON_TEXT_PART_TYPES:
        return ""
    for key in _TEXT_KEYS:
        text = _field(part, key)
        if isinstance(text, str):
            return text
    return ""

def flatten_message_text(content: Any, *, sep: str = "\n") -> str:
    """Return the visible text from common chat/Responses message content shapes."""
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return sep.join(chunk for chunk in map(_text_from_part, content) if chunk)
    text = _text_from_part(content)
    if text:
        return text
    try:
        return str(content)
    except Exception:
        return ""

def _sanitize_surrogates(text: str) -> str:
    """Replace lone surrogate code points with U+FFFD; no-op when none present."""
    # ``str.isascii`` is an O(1) flag check; surrogates are never ASCII, so the
    # regex scan only runs for the (rare) non-ASCII leaf.
    if text.isascii():
        return text
    return _SURROGATE_RE.sub('\ufffd', text)

def _tc_field(tc: Any, key: str) -> Any:
    """Read ``key`` from a tool-call entry that may be a dict or an SDK object."""
    return tc.get(key) if isinstance(tc, dict) else getattr(tc, key, None)

def coalesce_tool_call_id(tc: Any) -> str:
    """Effective call id of a tool_call entry (dict or object); ``""`` when none. Codex Responses
    carry ``call_id`` (authoritative pairing key), Chat Completions ``id`` only, and bridge ids
    may be ``call_id|response_item_id``."""
    for raw in (_tc_field(tc, "call_id"), _tc_field(tc, "id")):
        value = raw.strip() if isinstance(raw, str) else ""
        if value:
            return value.split("|", 1)[0].strip() or value
    return ""

def carrier_record(assistant_message: Any) -> Optional[dict]:
    """The private ``reasoning_details`` record for one response message, or None when it has no carrier."""
    record: dict[str, Any] = {}
    if sig := thought_signature(field(assistant_message, "extra_content")):
        record["extra_content"] = {"google": {"thought_signature": sig}}
    for key in ("reasoning_opaque", "reasoning_text"):
        value = field(assistant_message, key)
        if isinstance(value, str) and value:
            record[key] = value
    return {"type": CARRIER_TYPE, **record} if record else None

def _normalize_tool_call_id(tool_call_id: Any) -> Any:
    """Normalize a composite bridge id to its canonical call-id half."""
    if isinstance(tool_call_id, str) and "|" in tool_call_id:
        return tool_call_id.split("|", 1)[0].strip()
    return tool_call_id

def _detect_upstream_elision(content: Any) -> bool:
    """True when a string result carries provider-side elision markers (bounded scan)."""
    if not isinstance(content, str) or len(content) < _ELISION_SCAN_MIN_CHARS:
        return False
    window = content[:_ELISION_SCAN_MAX_CHARS]
    return any(p.search(window) for p in _UPSTREAM_ELISION_PATTERNS)

def _maybe_append_elision_notice(name: str, content: Any) -> Any:
    """Append the incompleteness notice to untrusted results with elision markers. A multimodal part list (an MCP
    result that also carries images) is judged by its first text part, which is where the notice goes."""
    if not _is_untrusted_tool(name):
        return content
    if isinstance(content, list):
        idx = next((i for i, item in enumerate(content) if _is_text_item(item)), None)
        if idx is not None and _detect_upstream_elision(content[idx]["text"]):
            return [*content[:idx], {**content[idx], "text": content[idx]["text"] + _UPSTREAM_ELISION_NOTICE},
                    *content[idx + 1:]]
        return content
    if _detect_upstream_elision(content):
        return content + _UPSTREAM_ELISION_NOTICE
    return content

def _tool_output_risk_metadata(name: str, content: Any) -> Optional[dict[str, Any]]:
    """Internal-only advisory classification of attacker-controlled output: deterministic
    finding ids, never blocks or redacts, omits the scanned text."""
    if not _is_untrusted_tool(name):
        return None
    if isinstance(content, str):
        text_parts = [content]
    elif isinstance(content, list):
        text_parts = [item["text"] for item in content if _is_text_item(item)]
    else:
        return None
    if not text_parts:
        return None

    findings: list[str] = []
    for text in text_parts:
        for finding in scan_for_threats(text, scope="context"):
            if finding not in findings:
                findings.append(finding)
    return {"risk": "high" if findings else "low", "findings": findings, "redacted": False}

def _neutralize_delimiters(content: str) -> str:
    """Defang embedded ``untrusted_tool_result`` tokens so poisoned content can't close the
    trust boundary early (hyphens keep it readable but non-matching)."""
    return _DELIMITER_TOKEN_RE.sub("untrusted-tool-result", content)

def _sanitize_message(
    msg: Any, strip_extra_content: bool, strip_reasoning: frozenset = frozenset(),
    native_reasoning_details_type: str | None = None, *, mistral_tool_ids: bool = False,
) -> dict | None:
    """Sanitized copy of ``msg``, or None when nothing needs stripping.

    Drops persistence sidecars, ``_``-prefixed scaffolding markers, tool-call ``call_id`` /
    ``response_item_id`` (and ``extra_content`` unless Gemini), an assistant
    ``tool_calls: []`` / ``null`` (strict providers reject both), ``name``
    on tool results (schema-valid only on user/assistant messages; strict
    providers reject it with ``contains item with unknown key name``), and the reasoning
    keys in ``strip_reasoning`` (carriers the route does not read, ``_wire_reasoning_carriers``).
    On a route that reads ``reasoning_details``, private ``<provider>.native_assistant`` carriers still go only to the
    profile that declared that exact type: another provider's signed replay is meaningless (or
    rejected) elsewhere, and stored history keeps it for a return to the original provider.
    ``mistral_tool_ids`` maps the call ``id`` and the result ``tool_call_id`` through
    ``_mistral_tool_id`` from the pairing key the result writers use (``coalesce_tool_call_id``:
    ``call_id`` first, call half of a composite ``call|item`` id), so each pair stays matched.
    """
    if not isinstance(msg, dict):
        return None
    strip_keys = [k for k in msg if k in _STRIP_MSG_KEYS or (isinstance(k, str) and k.startswith("_"))]
    if msg.get("role") == "assistant":
        strip_keys += [k for k in strip_reasoning if k in msg]
    kept_details = None
    if "reasoning_details" not in strip_keys and isinstance(msg.get("reasoning_details"), list):
        details = msg["reasoning_details"]
        kept = [d for d in details if not (
            isinstance(d, dict) and isinstance(d.get("type"), str)
            and d["type"].endswith(".native_assistant") and d["type"] != native_reasoning_details_type)]
        if len(kept) != len(details):
            strip_keys.append("reasoning_details")
            kept_details = kept
    # ``name`` is schema-valid on user/assistant messages, so the removal is
    # role-qualified: only tool results carry it illegally (strict providers
    # reject with "contains item with unknown key name").
    if msg.get("role") == "tool" and "name" in msg:
        strip_keys.append("name")
    out_msg = {k: v for k, v in msg.items() if k not in strip_keys}
    remapped = False
    if mistral_tool_ids and msg.get("role") == "tool":
        result_key = coalesce_tool_call_id({"id": msg.get("tool_call_id")})
        if result_key and (mapped := _mistral_tool_id(result_key)) != msg["tool_call_id"]:
            out_msg["tool_call_id"] = mapped
            remapped = True
    if kept_details:
        out_msg["reasoning_details"] = kept_details
    tool_calls = msg.get("tool_calls")
    copied_tool_calls = None
    if msg.get("role") == "assistant" and "tool_calls" in msg and (tool_calls is None or (isinstance(tool_calls, list) and not tool_calls)):
        out_msg.pop("tool_calls", None)
        strip_keys.append("tool_calls")
    elif isinstance(tool_calls, list):
        for tc_idx, tc in enumerate(tool_calls):
            if not isinstance(tc, dict):
                continue
            keys = [k for k in _STRIP_TC_KEYS if k in tc]
            if "extra_content" in tc and (
                strip_extra_content or not _has_replayable_thought_signature(tc["extra_content"])
            ):
                keys.append("extra_content")
            key = coalesce_tool_call_id(tc) if mistral_tool_ids else ""
            mapped = _mistral_tool_id(key) if key else None
            if keys or (mapped is not None and mapped != tc.get("id")):
                if copied_tool_calls is None:
                    copied_tool_calls = list(tool_calls)
                copied_tool_calls[tc_idx] = {k: v for k, v in tc.items() if k not in keys}
                if mapped is not None:
                    copied_tool_calls[tc_idx]["id"] = mapped
        if copied_tool_calls is not None:
            out_msg["tool_calls"] = copied_tool_calls
    return out_msg if strip_keys or remapped or copied_tool_calls is not None else None
